// ============================================================
// Capacity Constants (for utilization monitoring)
// ============================================================
const (
	MaxSizePublickeyId     int = 32768
	MaxSizePublickeyBase64 int = 32768
	MaxSizeKeyId           int = 32768
	MaxSizeKeyBase64       int = 32768
)

// ============================================================
// Merge: PublicKey
// ============================================================
// MergePublicKey fills zero-valued fields in dst from src.
func MergePublicKey(dst, src *PublicKey) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.Base64 == "" {
		dst.Base64 = src.Base64
	}
	if dst.Created == 0 {
		dst.Created = src.Created
	}
}

// ============================================================
// Merge: Key
// ============================================================
// MergeKey fills zero-valued fields in dst from src.
func MergeKey(dst, src *Key) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.Base64 == "" {
		dst.Base64 = src.Base64
	}
	if dst.Created == 0 {
		dst.Created = src.Created
	}
}
